from __future__ import annotations

def flatten(nested_list: list[int]) -> list[int]:
    """
    Flattens a nested list of integers of arbitrary depth.

    Parameters:
    - nested_list (list[int]): The nested list to flatten.

    Returns:
    - list[int]: A flattened list of integers.

    Complexity: O(n)
    """
    def _flatten_helper(lst, flat_list):
        for item in lst:
            if isinstance(item, list):
                _flatten_helper(item, flat_list)
            else:
                flat_list.append(item)
        return flat_list

    return _flatten_helper(nested_list, [])

